#include <bits/stdc++.h>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> ss;
    bool gg = false;

    for (int i = 0; i < n; i++) {
        int aux;
        cin >> aux;

        if (aux == 0 && !gg) continue;
        if (aux == 1) gg = true;

        ss.push_back(aux);
    }

    while (!ss.empty() && ss.back() != 1) {
        ss.pop_back();
    }

    int ans = 0;

    for (size_t i = 0; i < ss.size(); i++) {
        if (ss[i] == -1) {
            continue;
        }

        if (ss[i] == 1) {
            ans++;
        } else if (i + 1 < ss.size() && ss[i + 1] == 1) {
            ans++;
        } else {
            for (size_t j = i; j < ss.size() && ss[j] != 1; j++) {
                ss[j] = -1;
            }
        }
    }

    cout << ans << '\n';

    return 0;
}

